// Bundles the core into one file for the browser.
//
// Unity WebGL cannot import ES modules from a .jslib, and a bundler in the
// trust path is a bad property for something that pins money - IMPLEMENTATION
// section 3.6 says so about hashing. So this is deliberately the smallest
// possible bundler: it topologically sorts the imports, strips the import and
// export lines, and concatenates. No transforms, no minification, no renaming.
//
// The test that matters is bundle.test.js: the bundle must produce the same
// state hashes as the modules, or it is not the same core.

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve, relative } from 'node:path';

// WHICH CORE, UNDER WHICH NAME (kanban #523): by default the bundle versions 1-4 pin, dist/blwp-core.js of the frozen
// 68e2b3d6, byte for byte the file they name; ARENA_BUNDLE_SRC (a core tree), ARENA_BUNDLE_FILE and ARENA_BUNDLE_GLOBAL
// build another - version 5's cleaned cores: dist/core-<hash>.js, global NEXTBLOCK_CORE.
const SRC = process.env.ARENA_BUNDLE_SRC ? process.env.ARENA_BUNDLE_SRC.replace(/\/?$/, '/') : new URL('../frozen/68e2b3d6/', import.meta.url).pathname;
const FILE = process.env.ARENA_BUNDLE_FILE || 'blwp-core.js';
const GLOBAL = process.env.ARENA_BUNDLE_GLOBAL || 'BLWP';
const FROM = GLOBAL === 'BLWP' ? '@blwp/core' : 'the Next Block core';
// ARENA_BUNDLE_OUT builds into another directory, so a test can build this
// source and compare it with what is committed; unset, it writes dist/ as ever.
const OUT = process.env.ARENA_BUNDLE_OUT ? process.env.ARENA_BUNDLE_OUT.replace(/\/?$/, '/') : new URL('../dist/', import.meta.url).pathname;

import { concatBundle } from './concat-bundle.js';

// THE PAGE'S CORE: the simulator, its state layout, and the HUD's chart (WAR_TACTICS.md §0.3: a view the page reads,
// never a rule).
let { out, order } = concatBundle(SRC, ['sim.js', 'state.js', 'chart.js'],
  '// GENERATED by tools/bundle.js from ' + FROM + '. Do not edit.\n'
  + '// Verified against the module build by test/bundle.test.js.\n'
  + 'var ' + GLOBAL + ' = (function () {\n"use strict";\n');
// WHAT THE BROWSER BUNDLE OFFERS, AND WHAT IT DELIBERATELY DOES NOT.
//
// `setGround`, `setSolids` and `setHeat` were on this list. All three were
// host doors into the simulated world, and letters 36, 39 and 40 closed them
// in turn: the relief comes from the round's seed, the collision boxes are the
// map's own, and heat is what the core makes of a load that travels in the
// transcript. They still exist in `src/` for the tests that MEASURE what a
// host world was worth - a test is not a page - but a bundle that carried them
// would leave the page able to do what the bridge no longer asks for.
out += '\nreturn { init: init, step: step, hash: hash, runScore: runScore,\n';
out += '         groundAt: groundAt, teleport: teleport,\n';
out += '         restart: restart, frontAt: frontAt, submitLiquidation: submitLiquidation, submitSample: submitSample, submitTape: submitTape,\n';
out += '         chartView: chartView, chartPoint: chartPoint, CH_WORDS: CH_WORDS,\n';
out += '         candleView: candleView, CV_TOTAL: CV_TOTAL, terrainAt: terrainAt,\n';
out += '         submitLoad: submitLoad, heatOf: heatOf, cargoOf: cargoOf, roomFor: roomFor, bedFill: bedFill,\n';
out += '         create: create, WORDS: WORDS };\n})();\n';
out += 'if (typeof module !== "undefined") module.exports = ' + GLOBAL + ';\n';

mkdirSync(OUT, { recursive: true });
writeFileSync(OUT + FILE, out);

// The package is "type": "module", so Node would read this file as ESM - and
// an ESM file with no export statements has an empty namespace, which is
// exactly the empty object require() was handing back. The browser does not
// care either way; Node needs telling.
writeFileSync(OUT + 'package.json', JSON.stringify({ type: 'commonjs' }, null, 1) + '\n');
console.log('dist/' + FILE + '  ' + (out.length / 1024).toFixed(1) + ' KB  from ' + order.length + ' modules');
